CREATE TABLE `client_state` (
	`key` text PRIMARY KEY,
	`value` text NOT NULL
);

CREATE TABLE `source_key` (
	`source_id` text PRIMARY KEY,
	`album_artist_key` text,
	`artist_key` text,
	`album_key` text
);

CREATE TABLE `sync_queue` (
	`mutation_id` integer PRIMARY KEY,
	`mutation` text NOT NULL
);

CREATE TABLE `sync_scope` (
	`scope` text PRIMARY KEY,
	`change_seq` integer NOT NULL,
	`row_key` text,
	`loaded_at` integer
);

CREATE TABLE `source_segment` (
	`source_id` text NOT NULL,
	`position` integer NOT NULL,
	`recording_id` text,
	`raw_artist` text,
	`raw_title` text,
	`start_ms` integer,
	`end_ms` integer,
	CONSTRAINT `source_segment_pk` PRIMARY KEY(`source_id`, `position`)
);

CREATE INDEX `source_segment_recording_idx` ON `source_segment` (`recording_id`);

-- Groups that the client has already synced come again with their segments
DELETE FROM `client_state` WHERE `key` = 'catalogCursor';
